/// Erasure Receipt
///
/// The receipt of an erasure (PRV-353). reached and not-reached are sentences that name a copy, what happened to it or why it was not reached, and the task that closes the gap; changed names each record changed and the fields cleared, never their values. complete is true only when no copy is left unreached, which is false until the subject key of D-350 is built. batches is the number of commits the erasure took and batch-bound the most records one commit changes. reached also states the restriction of processing that was in force on the principal and each legal hold that kept a record unchanged (PRV-2463); not-reached lists each record a hold kept.
///
/// Specification type `erasure-receipt`: a struct.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct ErasureReceipt {
    /// Field `request`.
    pub request: String,
    /// Field `principal`.
    pub principal: PrincipalId,
    /// Field `at`.
    pub at: prelude::Timestamp,
    /// Field `records`.
    pub records: Vec<RecordId>,
    /// Field `changed`.
    pub changed: Vec<ErasedRecord>,
    /// Field `reached`.
    pub reached: Vec<String>,
    /// Field `not-reached`.
    pub not_reached: Vec<String>,
    /// Field `complete`.
    pub complete: bool,
    /// Field `batches`.
    pub batches: u32,
    /// Field `batch-bound`.
    pub batch_bound: u64,
}

/// Error Code
///
/// strata_protocol::api::ErrorCode, as it is written on the wire (snake_case); each has one HTTP status, the one system.generation.errorKinds gives the error kind of the same name.
///
/// Specification type `error-code`: an enumeration, serialised as the specification's values.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]

pub enum ErrorCode {
    /// The value `unauthenticated`.
    #[serde(rename = "unauthenticated")]
    Unauthenticated,
    /// The value `forbidden`.
    #[serde(rename = "forbidden")]
    Forbidden,
    /// The value `not_found`.
    #[serde(rename = "not_found")]
    NotFound,
    /// The value `conflict`.
    #[serde(rename = "conflict")]
    Conflict,
    /// The value `invalid`.
    #[serde(rename = "invalid")]
    Invalid,
    /// The value `throttled`.
    #[serde(rename = "throttled")]
    Throttled,
    /// The value `unavailable`.
    #[serde(rename = "unavailable")]
    Unavailable,
    /// The value `internal`.
    #[serde(rename = "internal")]
    Internal,
}

impl ErrorCode {
    /// The value as the specification writes it.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Unauthenticated => "unauthenticated",
            Self::Forbidden => "forbidden",
            Self::NotFound => "not_found",
            Self::Conflict => "conflict",
            Self::Invalid => "invalid",
            Self::Throttled => "throttled",
            Self::Unavailable => "unavailable",
            Self::Internal => "internal",
        }
    }
}

