/// strata_kernel::StateDelta: the logical change of one accepted transition.
///
/// Specification type `state-delta`: a struct.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct StateDelta {
    /// Field `tenant`.
    pub tenant: TenantId,
    /// Field `base-revision`.
    pub base_revision: Option<StateRevision>,
    /// Field `new-revision`.
    pub new_revision: StateRevision,
    /// Field `next-record`.
    pub next_record: u64,
    /// Field `event-seq`.
    pub event_seq: u64,
    /// Field `ops`.
    pub ops: Vec<DeltaOp>,
}

/// Event Body
///
/// strata_kernel::EventBody: the body of a domain event; roles is a BTreeSet<RoleId>. ledger-entry-posted is one entry recorded in an account (LDG-010, D-5008); owner is personal and is never logged.
///
/// Specification type `event-body`: a union, externally tagged.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum EventBody {
    /// The variant `tenant-created`.
    TenantCreated {
        /// Field `name`.
        name: String,
    },
    /// The variant `schema-changed`.
    SchemaChanged {
        /// Field `version`.
        version: SchemaVersion,
        /// Field `summary`.
        summary: Vec<String>,
        /// Field `grandfathered`.
        grandfathered: u64,
    },
    /// The variant `member-changed`.
    MemberChanged {
        /// Field `principal`.
        principal: PrincipalId,
        /// Field `roles`.
        #[serde(deserialize_with = "decode_set_role_id")]
        roles: std::collections::BTreeSet<RoleId>,
    },
    /// The variant `record-created`.
    RecordCreated {
        /// Field `record`.
        record: std::sync::Arc<Record>,
    },
    /// The variant `record-updated`.
    RecordUpdated {
        /// Field `before`.
        before: std::sync::Arc<Record>,
        /// Field `after`.
        after: std::sync::Arc<Record>,
        /// Field `transitions`.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        transitions: Option<std::collections::BTreeMap<WorkflowId, String>>,
    },
    /// The variant `record-deleted`.
    RecordDeleted {
        /// Field `before`.
        before: std::sync::Arc<Record>,
    },
    /// The variant `automation-suspended`.
    AutomationSuspended {
        /// Field `automation`.
        automation: WorkflowId,
        /// Field `definer`.
        definer: PrincipalId,
        /// Field `role`.
        role: RoleId,
    },
    /// The variant `setting-changed`.
    SettingChanged {
        /// Field `setting`.
        setting: SettingId,
        /// Field `level`.
        level: SettingLevel,
        /// Field `subject`.
        subject: String,
    },
    /// The variant `ledger-entry-posted`.
    LedgerEntryPosted {
        /// Field `account`.
        account: LedgerAccountId,
        /// Field `owner`.
        owner: LedgerOwner,
        /// Field `unit`.
        unit: LedgerUnit,
        /// Field `scope`.
        scope: LedgerScope,
        /// Field `amount`.
        amount: LedgerAmount,
        /// Field `balance`.
        balance: LedgerAmount,
        /// Field `balance-before`.
        balance_before: LedgerAmount,
        /// Field `entry-sequence`.
        entry_sequence: u64,
        /// Field `reason`.
        reason: String,
    },
}

/// Domain Event
///
/// strata_kernel::DomainEvent: a fact about an accepted transition; its sequence is gapless per tenant.
///
/// Specification type `domain-event`: a struct.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct DomainEvent {
    /// Field `tenant`.
    pub tenant: TenantId,
    /// Field `seq`.
    pub seq: u64,
    /// Field `revision`.
    pub revision: StateRevision,
    /// Field `at`.
    pub at: prelude::Timestamp,
    /// Field `principal`.
    pub principal: Principal,
    /// Field `correlation`.
    pub correlation: String,
    /// Field `body`.
    pub body: EventBody,
}

/// Effect
///
/// strata_kernel::Effect: something the adapters do after commit. start-automation and decline-automation are the outcome of a trigger that matched an event of the transition (D-7200): the automation worker creates the job of the run, or writes the declined exception record, in the commit of the transition (SCH-004, SCH-1532).
///
/// Specification type `effect`: a union, externally tagged.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Effect {
    /// The variant `publish`.
    Publish {
        /// Field `seq`.
        seq: u64,
    },
    /// The variant `revoke-sessions`.
    RevokeSessions {
        /// Field `principal`.
        principal: PrincipalId,
    },
    /// The variant `start-automation`.
    StartAutomation(AutomationStart),
    /// The variant `decline-automation`.
    DeclineAutomation(AutomationDecline),
}

/// Output
///
/// strata_kernel::Output: what an accepted transition tells its caller. operation is the output of an accepted invocation of a tenant operation: the records its steps created, the other records they changed and the records they deleted, each once in step order, and the ledger entries its postings made (OPR-1541).
///
/// Specification type `output`: a union, externally tagged.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Output {
    /// The variant `tenant`.
    Tenant,
    /// The variant `schema`.
    Schema {
        /// Field `version`.
        version: SchemaVersion,
    },
    /// The variant `member`.
    Member,
    /// The variant `record`.
    Record {
        /// Field `object`.
        object: ObjectTypeId,
        /// Field `id`.
        id: RecordId,
        /// Field `version`.
        version: u64,
    },
    /// The variant `deleted`.
    Deleted {
        /// Field `object`.
        object: ObjectTypeId,
        /// Field `id`.
        id: RecordId,
    },
    /// The variant `erased`.
    Erased {
        /// Field `changed`.
        changed: Vec<ErasedRecord>,
        /// Field `member-removed`.
        member_removed: bool,
        /// Field `teams`.
        teams: Vec<TeamId>,
        /// Field `invitations`.
        invitations: Vec<InvitationId>,
        /// Field `not-erased`.
        not_erased: Vec<String>,
        /// Field `more`.
        more: bool,
        /// Field `next-object`.
        next_object: Option<ObjectTypeId>,
        /// Field `next-after`.
        next_after: Option<RecordId>,
    },
    /// The variant `refreshed`.
    Refreshed {
        /// Field `changed`.
        changed: u64,
        /// Field `more`.
        more: bool,
        /// Field `next-after`.
        next_after: Option<RecordId>,
    },
    /// The variant `setting`.
    Setting {
        /// Field `setting`.
        setting: SettingId,
        /// Field `revision`.
        revision: u64,
    },
    /// The variant `operation`.
    Operation {
        /// Field `operation`.
        operation: TenantOperationId,
        /// Field `created`.
        created: Vec<RecordId>,
        /// Field `changed`.
        changed: Vec<RecordId>,
        /// Field `deleted`.
        deleted: Vec<RecordId>,
        /// Field `entries`.
        entries: Vec<LedgerEntry>,
    },
    /// The variant `ledger-posted`.
    LedgerPosted {
        /// Field `results`.
        results: Vec<LedgerPostingResult>,
    },
    /// The variant `expired`.
    Expired {
        /// Field `object`.
        object: ObjectTypeId,
        /// Field `deleted`.
        deleted: Vec<RecordId>,
        /// Field `kept`.
        kept: Vec<String>,
    },
}

