/// The pattern of type `segment-key`, matched against the whole value.
static SEGMENT_KEY_PATTERN: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new("\\A(?:^[a-z][a-z0-9_]*$)\\z").expect("specc checked that the pattern compiles")
});

/// segment-key
///
/// The id of a segment inside a bundle, [a-z][a-z0-9_]*, at most 64 bytes. The segment-id of an installed segment is derived from the tenant and this key (D-6583).
///
/// Specification type `segment-key`: an identifier represented as `string`.
///
/// A value matches `^[a-z][a-z0-9_]*$` and has a length of at most 64; decoding refuses one that does not, and [`SegmentKey::new`] checks it.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(try_from = "String", into = "String")]
pub struct SegmentKey(pub String);

impl SegmentKey {
    /// The value, when it meets the type's constraints.
    pub fn new(value: impl Into<String>) -> Result<Self, TypeConstraintViolation> {
        let value = Self(value.into());
        value.validate()?;
        Ok(value)
    }

    /// Checks the type's constraints.
    pub fn validate(&self) -> Result<(), TypeConstraintViolation> {
        if self.0.chars().count() > 64 {
            return Err(TypeConstraintViolation {
                type_id: "segment-key",
                constraint: "maxLength",
            });
        }
        if !SEGMENT_KEY_PATTERN.is_match(&self.0) {
            return Err(TypeConstraintViolation {
                type_id: "segment-key",
                constraint: "pattern",
            });
        }
        Ok(())
    }
}

impl TryFrom<String> for SegmentKey {
    type Error = TypeConstraintViolation;

    fn try_from(value: String) -> Result<Self, Self::Error> {
        Self::new(value)
    }
}

impl From<SegmentKey> for String {
    fn from(value: SegmentKey) -> Self {
        value.0
    }
}

impl SegmentKey {
    /// The value as text.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for SegmentKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

