/// Specification type `automation-decline`: a struct.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct AutomationDecline {
    /// Field `trigger`.
    pub trigger: TriggerId,
    /// Field `automation`.
    pub automation: WorkflowId,
    /// Field `event-seq`.
    pub event_seq: u64,
    /// Field `hop`.
    pub hop: u32,
    /// Field `reason`.
    pub reason: AutomationExceptionReason,
    /// Field `detail`.
    pub detail: String,
}

