/// Template Value Type
///
/// The type a template declares for a value it places: the shape of the value that the sender supplies (D-7900).
///
/// Specification type `template-value-type`: an enumeration, serialised as the specification's values.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize)]
pub enum TemplateValueType {
    /// The value `str`.
    #[serde(rename = "str")]
    Str,
    /// The value `int`.
    #[serde(rename = "int")]
    Int,
    /// The value `bool`.
    #[serde(rename = "bool")]
    Bool,
    /// The value `time`.
    #[serde(rename = "time")]
    Time,
}

impl TemplateValueType {
    /// The value as the specification writes it.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Str => "str",
            Self::Int => "int",
            Self::Bool => "bool",
            Self::Time => "time",
        }
    }
}

